<script setup>
import {computed} from 'vue';import {Bar,Line} from 'vue-chartjs';import {Chart as ChartJS,Title,Tooltip,Legend,BarElement,CategoryScale,LinearScale,PointElement,LineElement} from 'chart.js';import StatCard from '../components/StatCard.vue';import {getOverallStats,getCategoryStats,getAccuracyTrend,getWeakestBTKVTopics,getStrongestBTKVTopics,getSubcategoryStats} from '../utils/statistics';ChartJS.register(Title,Tooltip,Legend,BarElement,CategoryScale,LinearScale,PointElement,LineElement);const overall=computed(getOverallStats),cats=computed(()=>['SIMAK UI','LPDP','BTKV'].map(getCategoryStats)),trend=computed(getAccuracyTrend),subcats=computed(()=>getSubcategoryStats('BTKV'));const lineData=computed(()=>({labels:trend.value.map(x=>x.date),datasets:[{label:'Akurasi harian',data:trend.value.map(x=>x.accuracy),borderColor:'#2563eb'}]})),barData=computed(()=>({labels:cats.value.map(x=>x.category),datasets:[{label:'Akurasi kategori',data:cats.value.map(x=>x.accuracy),backgroundColor:['#1d4ed8','#7c3aed','#0f766e']}]}))
</script>
<template><section class="page"><h1>Statistik</h1><div class="stat-grid"><StatCard title="Total soal dikerjakan" :value="overall.totalAnswered"/><StatCard title="Total sesi" :value="overall.totalSessions"/><StatCard title="Streak" :value="`${overall.streak} hari`"/><StatCard title="Akurasi keseluruhan" :value="`${overall.accuracy}%`"/></div><div class="chart-grid"><div class="card"><h2>Progress harian</h2><Line :data="lineData"/></div><div class="card"><h2>Akurasi per kategori</h2><Bar :data="barData"/></div></div><div class="grid-two"><div class="card"><h2>Topik terlemah</h2><p v-if="!getWeakestBTKVTopics().length">Selesaikan latihan BTKV untuk mendapat rekomendasi.</p><ul><li v-for="t in getWeakestBTKVTopics()" :key="t.topic">{{t.topic}} — {{t.accuracy}}%</li></ul></div><div class="card"><h2>Topik terkuat</h2><p v-if="!getStrongestBTKVTopics().length">Belum ada data.</p><ul><li v-for="t in getStrongestBTKVTopics()" :key="t.topic">{{t.topic}} — {{t.accuracy}}%</li></ul></div></div><div class="card table-card"><h2>Akurasi per subkategori BTKV</h2><table><thead><tr><th>Subkategori</th><th>Dikerjakan</th><th>Akurasi</th><th>Rekomendasi</th></tr></thead><tbody><tr v-for="s in subcats" :key="s.subcategory"><td>{{s.subcategory}}</td><td>{{s.total}}</td><td>{{s.accuracy}}%</td><td>{{s.accuracy<70?'Latih kembali':'Pertahankan'}}</td></tr></tbody></table><p v-if="!subcats.length" class="empty">Data akan muncul setelah latihan.</p></div></section></template>
